import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

bp = extract(b)
ap = extract(a)
if bp == ap:
    print('MATCH: All package versions identical')
else:
    for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(k, 'MISSING')
        av = ap.get(k, 'MISSING')
        if bv != av:
            print(f'DIFF: {k} baseline={bv} after={av}')
"

